/**
 * Renders public/og.png (1200x630) from an inline SVG using the brand fonts.
 *
 * The fonts in scripts/fonts are static instances generated by
 * scripts/prepare-og-fonts.py — resvg cannot read woff2 or apply variable
 * font axes. The lockup is the extracted brand artwork, inlined as a data URI.
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { Resvg } from '@resvg/resvg-js'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const FONT_DIR = join(ROOT, 'scripts', 'fonts')
const OUTPUT = join(ROOT, 'public', 'og.png')
const LOCKUP = join(ROOT, 'public', 'logo-lockup.png')

const WIDTH = 1200
const HEIGHT = 630

const BACKGROUND = '#141A30'
const BRAND = '#B9A5F5'
const FOREGROUND = '#F2F1F8'
const MUTED = '#A3A2BE'
const HAIRLINE = 'rgba(255,255,255,0.10)'

/** Displayed size of the lockup, preserving its aspect ratio. */
const LOCKUP_W = 236
const LOCKUP_H = 77

const fontFiles = readdirSync(FONT_DIR)
  .filter((file) => file.endsWith('.ttf'))
  .map((file) => join(FONT_DIR, file))

if (fontFiles.length === 0) {
  console.error(
    `No fonts found in ${FONT_DIR}.\n` +
      'Run `python scripts/prepare-og-fonts.py` first (needs brotli + fonttools).',
  )
  process.exit(1)
}

const lockupData = readFileSync(LOCKUP).toString('base64')

const svg = `
<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
  <defs>
    <linearGradient id="edge" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="${BRAND}" stop-opacity="0.55"/>
      <stop offset="0.5" stop-color="${BRAND}" stop-opacity="0.12"/>
      <stop offset="1" stop-color="${BRAND}" stop-opacity="0"/>
    </linearGradient>
    <radialGradient id="glow" cx="0.82" cy="0.12" r="0.72">
      <stop offset="0" stop-color="${BRAND}" stop-opacity="0.2"/>
      <stop offset="1" stop-color="${BRAND}" stop-opacity="0"/>
    </radialGradient>
    <pattern id="grid" width="64" height="64" patternUnits="userSpaceOnUse">
      <path d="M64 0H0V64" fill="none" stroke="#FFFFFF" stroke-opacity="0.045" stroke-width="1"/>
    </pattern>
    <mask id="gridMask">
      <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#gridFade)"/>
    </mask>
    <radialGradient id="gridFade" cx="0.5" cy="0.1" r="0.85">
      <stop offset="0" stop-color="#FFFFFF" stop-opacity="0.9"/>
      <stop offset="1" stop-color="#FFFFFF" stop-opacity="0"/>
    </radialGradient>
  </defs>

  <rect width="${WIDTH}" height="${HEIGHT}" fill="${BACKGROUND}"/>
  <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#grid)" mask="url(#gridMask)"/>
  <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#glow)"/>
  <rect x="0" y="0" width="${WIDTH}" height="3" fill="url(#edge)"/>

  <image x="80" y="68" width="${LOCKUP_W}" height="${LOCKUP_H}" preserveAspectRatio="xMinYMid meet" href="data:image/png;base64,${lockupData}"/>

  <text x="80" y="238" font-family="JetBrains Mono" font-size="16" font-weight="500" letter-spacing="3.4" fill="${BRAND}">DIGITAL SOLUTIONS &amp; TECHNOLOGY</text>

  <text x="80" y="316" font-family="Space Grotesk" font-size="66" font-weight="700" letter-spacing="-2.4" fill="${FOREGROUND}">Your Vision.</text>
  <text x="80" y="390" font-family="Space Grotesk" font-size="66" font-weight="700" letter-spacing="-2.4" fill="${FOREGROUND}">Our Technology.</text>
  <text x="80" y="464" font-family="Space Grotesk" font-size="66" font-weight="700" letter-spacing="-2.4" fill="${BRAND}">Better Business.</text>

  <line x1="80" y1="512" x2="1120" y2="512" stroke="${HAIRLINE}" stroke-width="1"/>

  <text x="80" y="556" font-family="Space Grotesk" font-size="24" font-weight="500" letter-spacing="0.4" fill="${MUTED}">Build. Modernize. Maintain. Grow.</text>
</svg>
`

const resvg = new Resvg(svg, {
  fitTo: { mode: 'width', value: WIDTH },
  font: {
    fontFiles,
    loadSystemFonts: false,
    defaultFontFamily: 'Space Grotesk',
  },
})

writeFileSync(OUTPUT, resvg.render().asPng())
console.log(`wrote ${OUTPUT} (${readFileSync(OUTPUT).length} bytes)`)
